def prumer(cisla):
    # Prázdný seznam nemá průměr a dělili bychom nulou.
    if not cisla:
        return None
    return sum(cisla) / len(cisla)


# Testy běžného, jediného i prázdného vstupu.
assert prumer([2, 4, 6]) == 4
assert prumer([5]) == 5
assert prumer([]) is None
print("Průměr ověřen")
